fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // Since every pair-sum is guaranteed < 256, all values must be < 256.
    // We build 256 buckets, one per possible value.
    let mut buckets: Vec<Vec<usize>> = vec![Vec::new(); 256];
    for (i, &v) in nums.iter().enumerate() {
        let vi = v as usize;
        // vi < 256 is guaranteed by the problem statement
        buckets[vi].push(i);
    }

    // Now scan p from 0 upwards to find the lexicographically smallest (p, q).
    for p in 0..n {
        let a = nums[p];
        // if a > target, a + anything would exceed target, skip
        if a > target {
            continue;
        }
        let c = (target - a) as usize;
        if c >= buckets.len() {
            continue;
        }
        let bucket = &buckets[c];
        if bucket.is_empty() {
            continue;
        }
        // We need the smallest index q in `bucket` with q > p.
        // Since bucket is sorted by insertion order (and we inserted in increasing i),
        // we can binary‐search for p+1.
        let min_q = p + 1;
        match bucket.binary_search(&min_q) {
            Ok(idx) => {
                // exact match: bucket[idx] == p+1, which certainly is > p
                return (p, bucket[idx]);
            }
            Err(idx) => {
                // idx is the insertion point: the first bucket[*] > p
                if idx < bucket.len() {
                    return (p, bucket[idx]);
                }
            }
        }
    }

    // Problem statement guarantees at least one solution exists.
    unreachable!("two_sum guaranteed to find a pair");
}

