    #[test]
    fn duplicate_values() {
        let v = vec![1, 2, 2, 3];
        // target = 4; valid pairs are (1,3)->(0,3) and (2,2)->(1,2).
        // Lexicographically smallest is (0,3).
        assert_eq!(two_sum(&v, 4), (0, 3));
    }
